router.post("/invitations", ...inviteChain);
router.post("/:id/reset-password", requirePermission("user_management", "update"), asyncHandler(async (req, res) => {
  const bcrypt = require("bcryptjs");
  const { prisma } = require("../config/db");
  await prisma.user.updateMany({ where: { id: req.params.id, orgId: req.user.orgId }, data: { passwordHash: await bcrypt.hash(String(req.body?.password || "Temp-Passw0rd1"), 12) } });
  return sendSuccess(res, { reset: true });
}));
